const workbookRecalcRequestSchema = object({
  sessionId: string().uuid(),
  edits: array(
    object({
      sheetId: string().min(1),
      row: number().int().nonnegative().max(1048575),
      column: number().int().nonnegative().max(16383),
      input: string().max(32767)
    }).strict()
  ).max(1e4),
  reads: array(
    object({
      sheetId: string().min(1),
      range: object({
        startRow: number().int().nonnegative(),
        endRow: number().int().nonnegative(),
        startColumn: number().int().nonnegative(),
        endColumn: number().int().nonnegative()
      }).strict()
    }).strict()
  ).max(200)
}).strict().superRefine((request, context) => {
  let total = 0;
  for (const read of request.reads) {
    const { range: range2 } = read;
    if (range2.startRow > range2.endRow || range2.startColumn > range2.endColumn) {
      context.addIssue({ code: "custom", message: "Range boundaries are reversed." });
      return;
    }
    total += (range2.endRow - range2.startRow + 1) * (range2.endColumn - range2.startColumn + 1);
  }
  if (total > MAX_RANGE_CELLS) {
    context.addIssue({ code: "custom", message: `Recalc read exceeds ${MAX_RANGE_CELLS} cells.` });
  }
});
